<script setup>
import { ref, computed, watch } from 'vue';
import Icon from './Icon.vue';
import { data, day, doctor, labels, emrFields, notify, confirmAction } from '../store.js';
const props=defineProps({page:String});const emit=defineEmits(['navigate']);
const filter=ref('all');const selected=ref(2001);const draft=ref({});const error=ref('');const saved=ref('');
const visits=computed(()=>data.appointments.filter(a=>a.doctor_id===9&&a.status!=='cancelled'&&(filter.value==='all'||a.status===filter.value)));
const current=computed(()=>data.appointments.find(a=>a.id===Number(selected.value)));
const locked=computed(()=>data.records[selected.value]?.status==='locked');
function load(){draft.value={...Object.fromEntries(emrFields.map(f=>[f.key,''])),...data.records[selected.value]?.sections};error.value='';saved.value='';}
watch(selected,load);watch(()=>props.page,()=>load(),{immediate:true});
function open(a){selected.value=a.id;load();emit('navigate','emr');}
function start(a){if(a.status!=='booked')return notify('VISIT_BAD_STATE：当前不是待接诊状态','error');a.status='visiting';notify('演示接诊已开始');open(a);}
function finish(a){if(a.status!=='visiting')return notify('VISIT_BAD_STATE：请先开始接诊','error');if(data.records[a.id]?.status!=='locked')return notify('EMR_NOT_LOCKED：请先提交锁定病历','error');confirmAction('确认完成本次就诊？','病历已锁定，就诊将变为已完成。',()=>{a.status='done';notify('演示就诊已完成');});}
function noShow(a){confirmAction('标记演示爽约？','患者未到诊时才应执行此操作。',()=>{if(a.status!=='booked')return notify('仅待接诊预约可标记爽约','error');a.status='no_show';notify('已标记演示爽约');},true);}
function save(){if(locked.value)return notify('EMR_LOCKED：锁定病历不能编辑','error');for(const f of emrFields)if((draft.value[f.key]||'').length>f.max){error.value=`${f.label}超过字符上限`;return false;}data.records[selected.value]={status:'draft',sections:{...draft.value}};saved.value='刚刚保存';notify('演示草稿已保存 · 刷新后不保留');return true;}
function submitLock(){error.value='';if(!draft.value.diagnosis?.trim()||!draft.value.treatment?.trim()){error.value='提交锁定前必须填写诊断和处理意见。';notify(error.value,'error');return;}confirmAction('提交并锁定病历？','锁定后医生不可修改。此处仅对演示记录生效。',()=>{if(save()){data.records[selected.value].status='locked';notify('演示病历已锁定，可以完成就诊');}});}
function prefill(){if(locked.value||data.records[selected.value])return notify('仅首次创建的病历允许预填','warning');if(!data.intake.complete)return notify('请先在患者端完成六项预问诊演示','warning');const a=data.intake.answers;draft.value.chief_complaint=a[0];draft.value.present_illness=`持续时间：${a[1]}；影响程度：${a[2]}；伴随症状：${a[3]}`;draft.value.past_history=a[4];draft.value.allergy_history=a[5];notify('已用演示预问诊摘要预填前四段');}
</script>
<template>
<div v-if="page==='queue'"><div class="summary-strip"><div><strong>{{data.appointments.filter(a=>a.doctor_id===9&&a.status==='booked').length}}</strong><span>等待接诊</span></div><div><strong>{{data.appointments.filter(a=>a.doctor_id===9&&a.status==='visiting').length}}</strong><span>接诊中</span></div><div><strong>{{data.appointments.filter(a=>a.doctor_id===9&&a.status==='done').length}}</strong><span>已完成</span></div></div><section class="card"><div class="section-heading"><h2>李医生的接诊队列</h2><label class="inline-row">状态<select v-model="filter"><option value="all">全部</option><option value="booked">待接诊</option><option value="visiting">接诊中</option><option value="done">已完成</option></select></label></div><article v-for="a in visits" :key="a.id" class="visit-item"><span class="queue-number">{{String(a.seq_no).padStart(2,'0')}}</span><div class="visit-info"><h3>患者 #{{a.patient_id}} <span class="badge" :class="a.status">{{labels[a.status]}}</span></h3><p>{{a.visit_date}} · {{a.period==='AM'?'上午':'下午'}} · 预约 #{{a.id}}</p><span class="small-text muted">病历：{{data.records[a.id]?labels[data.records[a.id].status]:'未创建'}}</span></div><div class="visit-actions"><button class="button secondary" @click="open(a)">查看病历</button><button v-if="a.status==='booked'" class="button" @click="start(a)">开始接诊</button><button v-if="a.status==='visiting'" class="button" @click="finish(a)">完成就诊</button><button v-if="a.status==='booked'" class="text-button danger-text" @click="noShow(a)">标记爽约</button></div></article><div v-if="!visits.length" class="empty-state"><Icon name="list" :size="32"/><h3>当前筛选没有接诊记录</h3></div></section><div class="alert-banner info space-top" data-reading-aid="依据"><Icon name="shield"/><p>完成就诊的前置条件：病历已锁定。医生身份只能由真实服务端令牌派生，不接受前端传入 doctor_id。</p></div></div>
<div v-else class="emr-layout"><section class="card"><div class="section-heading"><h2>七段式电子病历</h2><span class="badge" :class="locked?'locked':'draft'">{{locked?'已锁定 · 只读':'草稿 · 可编辑'}}</span></div><label class="field">选择演示就诊记录<select v-model="selected"><option v-for="a in data.appointments.filter(a=>a.doctor_id===9&&a.status!=='cancelled')" :key="a.id" :value="a.id">#{{a.id}} · 患者 #{{a.patient_id}} · 序号 {{a.seq_no}}</option></select></label><div class="emr-toolbar"><span class="small-text muted">{{current?.visit_date}} · {{current?.period==='AM'?'上午':'下午'}} · {{saved||'未保存新修改'}}</span><button class="text-button" :disabled="locked" @click="prefill"><Icon name="plus" :size="14"/>首次预问诊预填</button></div><div v-if="error" class="alert-banner danger" role="alert">{{error}}</div><div class="emr-fields"><label v-for="(f,n) in emrFields" :key="f.key" class="field"><span class="emr-label"><span><b>{{String(n+1).padStart(2,'0')}}</b> {{f.label}} <span v-if="f.required" class="required">锁定必填</span></span><span class="small-text muted">{{draft[f.key]?.length||0}} / {{f.max}}</span></span><textarea v-model="draft[f.key]" :maxlength="f.max" :readonly="locked" rows="3" :placeholder="`填写${f.label}（演示内容）`"></textarea></label></div><div class="emr-savebar"><span class="small-text muted"><Icon name="lock" :size="15"/>{{locked?'锁定后只读，仅管理员可重新开放':'诊断与处理意见为提交锁定必填项'}}</span><div class="button-row"><button class="button secondary" :disabled="locked" @click="save">保存草稿</button><button class="button" :disabled="locked" @click="submitLock"><Icon name="lock" :size="16"/>提交锁定</button></div></div></section><aside class="card sticky-card" data-reading-aid="讲解"><h2>记录原则</h2><ol class="note-list"><li>先开始接诊，再完善七段病历。</li><li>主诉等字段允许草稿为空。</li><li>诊断与处理意见必填才可锁定。</li><li>锁定后医生不可修改。</li><li>锁定完成后再结束就诊。</li></ol><div class="soft-panel" data-reading-aid="演示"><Icon name="shield"/><p>所有文本都是演示内容，不能作为医疗记录使用。</p></div><button class="text-button space-top" @click="emit('navigate','queue')">返回接诊队列<Icon name="arrow" :size="16"/></button></aside></div>
</template>
